import React, { useState, useEffect } from 'react';
import { productsApi, usersApi, categoriesApi } from '../services/api';

const Dashboard = () => {
  const [stats, setStats] = useState({
    products: 0,
    users: 0,
    categories: 0,
  });

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const [productsRes, usersRes, categoriesRes] = await Promise.all([
          productsApi.getAll({ pageSize: 1 }),
          usersApi.getAll({ pageSize: 1 }),
          categoriesApi.getAll(),
        ]);
        setStats({
          products: productsRes.data.totalCount || productsRes.data.length || 0,
          users: usersRes.data.totalCount || usersRes.data.length || 0,
          categories: categoriesRes.data.length || 0,
        });
      } catch (error) {
        console.error('Failed to fetch stats:', error);
      }
    };
    fetchStats();
  }, []);

    return (
        <>
            <div className="content-header">
                <div className="container-fluid">
                    <h1 className="m-0">Dashboard</h1>
                </div>
            </div>

            <section className="content">
                <div className="container-fluid">
                    {/* Hàng chứa các ô thống kê[cite: 43] */}
                    <div className="row">
                        <div className="col-lg-4 col-6">
                            <div className="small-box bg-info">
                                <div className="inner">
                                    <h3>{stats.products}</h3>
                                    <p>Products</p>
                                </div>
                                <div className="icon"><i className="fas fa-shopping-cart"></i></div>
                                <Link to="/products" className="small-box-footer">More info <i className="fas fa-arrow-circle-right"></i></Link>
                            </div>
                        </div>

                        <div className="col-lg-4 col-6">
                            <div className="small-box bg-success">
                                <div className="inner">
                                    <h3>{stats.categories}</h3>
                                    <p>Categories</p>
                                </div>
                                <div className="icon"><i className="fas fa-tags"></i></div>
                                <Link to="/categories" className="small-box-footer">More info <i className="fas fa-arrow-circle-right"></i></Link>
                            </div>
                        </div>

                        <div className="col-lg-4 col-6">
                            <div className="small-box bg-warning">
                                <div className="inner">
                                    <h3>{stats.users}</h3>
                                    <p>Users</p>
                                </div>
                                <div className="icon"><i className="fas fa-users"></i></div>
                                <Link to="/users" className="small-box-footer">More info <i className="fas fa-arrow-circle-right"></i></Link>
                            </div>
                        </div>
                    </div>

                    {/* Thẻ card chào mừng ở dưới[cite: 43] */}
                    <div className="card">
                        <div className="card-header"><h3 className="card-title">Welcome to BaseCore Sales System</h3></div>
                        <div className="card-body">
                            <p>This is a teaching framework for web development using...</p>
                            {/* Thêm danh sách tính năng như trong ảnh của ní[cite: 43] */}
                        </div>
                    </div>
                </div>
            </section>
        </>
    );
};

export default Dashboard;
